/* @lc app=leetcode id=3960 lang=kotlin */ class Solution { fun getLength(nums: IntArray): Int = nums.indices.maxOf { i -> HashMap<Int, Int>().let { cnt -> HashMap<Int, Int>().let { ff -> (i until nums.size).fold(0) { best, j -> (cnt[nums[j]] ?: 0).let { c -> (if (c > 0) ff.merge(c, -1) { a, b -> a + b }.let { if (it == 0) ff.remove(c) } else Unit).let { cnt.put(nums[j], c + 1).let { ff.merge(c + 1, 1) { a, b -> a + b }.let { if (cnt.size == 1 || (ff.size == 2 && ff.keys.sorted().let { k -> k[1] == 2 * k[0] })) maxOf(best, j - i + 1) else best } } } } } } } } }